package com.hospital.smartqueue.patient.api; import com.hospital.smartqueue.patient.application.PatientService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/hospitals/{hospitalId}/patients") public class PatientController {private final PatientService service; public PatientController(PatientService s){service=s;} @PostMapping @ResponseStatus(HttpStatus.CREATED) public PatientResponse register(@PathVariable UUID hospitalId,@Valid @RequestBody RegisterPatientRequest request){return PatientResponse.from(service.register(hospitalId,request));}}
